-- Core data model for CalSnap (spec 0002).
--
-- GENERATED by `npm run gen:supabase-migration` from the table declarations
-- in src/data/schema/. Do not edit this file by hand: the SQLite migration in
-- src/db/migrations.ts comes from the same declarations, and editing one side
-- here is exactly the drift the generator exists to prevent.
--
-- Row level security is enabled AND forced on every table, with one policy
-- testing user_id and an index on user_id because that policy runs on every
-- row touched. auth.uid() is wrapped in a select so Postgres evaluates it
-- once per statement rather than once per row.

create table public.profiles (
  user_id uuid not null references auth.users(id) on delete cascade,
  age_years integer not null check (age_years between 13 and 120),
  age_recorded_on date not null,
  sex text not null check (sex in ('female', 'male')),
  height_cm numeric(5,1) not null check (height_cm > 0),
  activity_level text not null check (activity_level in ('sedentary', 'light', 'moderate', 'active', 'very_active')),
  goal_direction text not null check (goal_direction in ('lose', 'hold', 'gain')),
  goal_rate_kg_per_week numeric(3,2) not null default 0 check (goal_rate_kg_per_week between 0 and 1.5),
  goal_weight_kg numeric(5,2),
  unit_preference text not null default 'metric' check (unit_preference in ('metric', 'imperial')),
  timezone text not null,
  exercise_credit text not null default 'full' check (exercise_credit in ('none', 'full', 'partial')),
  exercise_credit_factor numeric(3,2) not null default 1 check (exercise_credit_factor between 0 and 1),
  photo_sync_enabled boolean not null default false,
  consented_at timestamptz,
  consent_version text,
  onboarded_at timestamptz,
  created_at timestamptz not null,
  updated_at timestamptz not null,
  primary key (user_id)
);

alter table public.profiles enable row level security;
alter table public.profiles force row level security;

create policy profiles_own_rows on public.profiles
  for all to authenticated
  using      (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create table public.meal_scans (
