create index meal_items_user_id_idx on public.meal_items (user_id);
create index meal_items_user_name_lower_idx on public.meal_items (user_id, lower(name));

alter table public.meal_items enable row level security;
alter table public.meal_items force row level security;

create policy meal_items_own_rows on public.meal_items
